#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#define MAGIC "!<arch>\n"
typedef struct {char name[256];unsigned char *data;size_t len;} Member;
static Member members[4096];static size_t count;
static void die(const char *s){fprintf(stderr,"x86-ar: %s\n",s);exit(1);}
static unsigned char *load(const char *path,size_t *n){FILE*f=fopen(path,"rb");long z;unsigned char*p;if(!f){perror(path);exit(1);}if(fseek(f,0,SEEK_END)||(z=ftell(f))<0||fseek(f,0,SEEK_SET))die("seek failed");p=malloc(z?z:1);if(!p)die("out of memory");if(fread(p,1,z,f)!=(size_t)z)die("read failed");fclose(f);*n=(size_t)z;return p;}
static const char*base(const char*p){const char *q=strrchr(p,'/'),*r=strrchr(p,'\\');if(r&&(!q||r>q))q=r;return q?q+1:p;}
static void add(const char*name,const unsigned char*p,size_t n){if(count>=4096)die("too many members");if(strlen(name)>255)die("member name too long");strcpy(members[count].name,name);members[count].data=malloc(n?n:1);if(!members[count].data)die("out of memory");memcpy(members[count].data,p,n);members[count++].len=n;}
static void read_archive(const char*path,int optional){FILE*f=fopen(path,"rb");unsigned char*b;size_t n,pos;if(!f){if(optional)return;perror(path);exit(1);}fclose(f);b=load(path,&n);if(n<8||memcmp(b,MAGIC,8))die("invalid archive magic");pos=8;while(pos<n){char name[257],sizebuf[11];size_t sz,k;if(n-pos<60||b[pos+58]!='`'||b[pos+59]!='\n')die("bad member header");memcpy(sizebuf,b+pos+48,10);sizebuf[10]=0;sz=(size_t)strtoull(sizebuf,NULL,10);memcpy(name,b+pos,16);name[16]=0;for(k=16;k&&name[k-1]==' ';k--);name[k]=0;if(k&&name[k-1]=='/')name[k-1]=0;pos+=60;if(sz>n-pos)die("truncated archive");if(strcmp(name,"/")&&strcmp(name,"//")&&name[0])add(name,b+pos,sz);pos+=sz+(sz&1);if(pos>n)die("truncated padding");}free(b);}
static void write_archive(const char*path){FILE*f=fopen(path,"wb");size_t i;if(!f){perror(path);exit(1);}fwrite(MAGIC,1,8,f);for(i=0;i<count;i++){char h[61],name[258];size_t k;Member*m=&members[i];if(strlen(m->name)>15)die("member name exceeds 15 chars (long names not implemented)");snprintf(name,sizeof(name),"%s/",m->name);memset(h,' ',60);memcpy(h,name,strlen(name));memcpy(h+16,"0           ",12);memcpy(h+28,"0     ",6);memcpy(h+34,"0     ",6);memcpy(h+40,"100644  ",8);{char z[32];snprintf(z,sizeof(z),"%zu",m->len);for(k=0;z[k];k++)h[48+k]=z[k];}h[58]='`';h[59]='\n';fwrite(h,1,60,f);fwrite(m->data,1,m->len,f);if(m->len&1)fputc('\n',f);}if(fclose(f))die("write failed");}
int main(int argc,char**argv){char op;int i;if(argc<3)die("usage: x86-ar [rcs|t|x] archive.a [objects...]");op=argv[1][0];if(op=='r'){read_archive(argv[2],1);for(i=3;i<argc;i++){size_t n,j;const char*name=base(argv[i]);unsigned char*p=load(argv[i],&n);for(j=0;j<count;j++)if(!strcmp(members[j].name,name))break;if(j<count){free(members[j].data);members[j].data=p;members[j].len=n;}else{add(name,p,n);free(p);}}write_archive(argv[2]);}else if(op=='t'||op=='x'){read_archive(argv[2],0);for(i=0;i<(int)count;i++){Member*m=&members[i];FILE*f;if(op=='t'){puts(m->name);continue;}f=fopen(m->name,"wb");if(!f){perror(m->name);return 1;}if(fwrite(m->data,1,m->len,f)!=m->len||fclose(f))die("extract failed");}}else die("unsupported operation");return 0;}
